const src = $('Normalize Check In').first().json;
const raw = String($json.output || '');
const a = raw.indexOf('{');
const b = raw.lastIndexOf('}');
let p = {};
try { p = JSON.parse(raw.slice(a, b + 1)); } catch (e) { p = {}; }
const allowed = ['on_time', 'at_risk', 'exception'];
let risk = String(p.risk_level || '').trim().toLowerCase();
if (allowed.indexOf(risk) === -1) { risk = 'on_time'; }
const statuses = ['booked', 'loaded', 'in_transit', 'at_delivery', 'delivered', 'delayed', 'breakdown', 'exception'];
let status = String(p.normalized_status || '').trim().toLowerCase().replace(/[^a-z_]/g, '');
if (statuses.indexOf(status) === -1) { status = 'in_transit'; }
const delayMinutes = Math.max(0, parseInt(p.delay_minutes, 10) || 0);
return [{ json: {
  check_in_id: src.check_in_id,
  load_id: src.load_id,
  driver_name: src.driver_name,
  received_at: src.received_at,
  status_raw: src.status_note,
  location: src.location,
  eta_text: src.eta_text,
  source: src.source,
  normalized_status: status,
  eta_iso: String(p.eta_iso || '').trim(),
  delay_minutes: delayMinutes,
  delay_reason: String(p.delay_reason || '').trim(),
  ai_risk_level: risk,
  risk_note: String(p.risk_note || '').trim(),
  customer_update: String(p.customer_update || '').trim(),
  next_check_in_minutes: Math.min(720, Math.max(30, parseInt(p.next_check_in_minutes, 10) || 180))
} }];

const src = $('Build Check In Record').first().json;
const rows = $input.all().map(function (i) { return i.json; });
let row = null;
for (const r of rows) {
  if (r && String(r.load_id || '').trim().toUpperCase() === src.load_id) { row = r; }
}
const NL = String.fromCharCode(10);
let etaIso = src.eta_iso;
let hoursLate = 0;
const appt = row ? String(row.delivery_appt || '').trim() : '';
if (appt && etaIso) {
  try {
    hoursLate = Math.round(DateTime.fromISO(etaIso).diff(DateTime.fromISO(appt), 'hours').hours * 10) / 10;
  } catch (e) { hoursLate = 0; }
}
if (!(hoursLate > 0)) { hoursLate = 0; }
let risk = src.ai_risk_level;
if (risk !== 'exception' && src.normalized_status !== 'delivered') {
  if (hoursLate >= 6) { risk = 'exception'; }
  else if (hoursLate >= 2) { risk = 'at_risk'; }
}
const lateNote = hoursLate > 0
  ? 'Running about ' + hoursLate + ' hour(s) past the delivery appointment.'
  : 'Still inside the delivery window.';
const customer = row ? String(row.customer || '') : '';
const destination = row ? String(row.destination || '') : '';
const origin = row ? String(row.origin || '') : '';
const delivered = src.normalized_status === 'delivered';
const head = risk === 'exception'
  ? ':rotating_light: *Exception on ' + src.load_id + '*'
  : (delivered ? ':white_check_mark: *Delivered ' + src.load_id + '*' : ':warning: *At risk: ' + src.load_id + '*');
return [{ json: {
  check_in_id: src.check_in_id,
  load_id: src.load_id,
  driver_name: src.driver_name,
  received_at: src.received_at,
  status_raw: src.status_raw,
  location: src.location,
  eta_text: src.eta_text,
  normalized_status: src.normalized_status,
  eta_iso: etaIso,
  delay_minutes: src.delay_minutes,
  delay_reason: src.delay_reason,
  risk_level: risk,
  ai_risk_level: src.ai_risk_level,
  risk_note: src.risk_note,
  hours_late: hoursLate,
  board_found: !!row,
  customer: customer,
  customer_email: row ? String(row.customer_email || '') : '',
  carrier: row ? String(row.carrier || '') : '',
  origin: origin,
  destination: destination,
  delivery_appt: appt,
  customer_update: src.customer_update,
  alert_text: head + NL
    + 'Customer: ' + (customer || 'not on the board') + NL
    + 'Driver: ' + (src.driver_name || 'unknown') + ' (' + (row ? String(row.carrier || '') : 'carrier unknown') + ')' + NL
    + 'Lane: ' + (origin || '?') + ' to ' + (destination || '?') + NL
    + 'Driver said: ' + (src.status_raw || '-') + NL
    + 'ETA: ' + (etaIso || 'not given') + NL
    + lateNote + NL
    + 'Desk note: ' + (src.risk_note || '-'),
  customer_message: 'Hi, a quick update on load ' + src.load_id + ' (' + (origin || 'origin') + ' to ' + (destination || 'destination') + '). '
    + (src.customer_update || src.risk_note || 'The load is moving and we are watching it.') + ' ' + lateNote,
  delivered_text: ':white_check_mark: *Delivered ' + src.load_id + '*' + NL
    + 'Customer: ' + (customer || 'not on the board') + NL
    + 'Driver: ' + (src.driver_name || 'unknown') + NL
    + 'Lane: ' + (origin || '?') + ' to ' + (destination || '?') + NL
    + 'Driver said: ' + (src.status_raw || '-'),
  delivered_message: 'Hi, load ' + src.load_id + ' arrived at ' + (destination || 'the delivery site') + ' and the paperwork is signed. '
    + 'We will send the proof of delivery with the invoice. Thanks for the business.',
  logged_at: $now.toISO()
} }];

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.load_id; });
const silenceHours = 8;
const apptWindowHours = 12;
const lines = [];
for (const r of rows) {
  const st = String(r.status || '').trim().toLowerCase();
  if (st === 'delivered' || st === 'cancelled') { continue; }
  const lc = String(r.last_check_in || '').trim();
  let hoursSince = null;
  if (lc) {
    try { hoursSince = Math.round($now.diff(DateTime.fromISO(lc), 'hours').hours * 10) / 10; } catch (e) { hoursSince = null; }
  }
  const silent = (hoursSince === null) || (hoursSince >= silenceHours);
  const da = String(r.delivery_appt || '').trim();
  let hoursToAppt = null;
  if (da) {
    try { hoursToAppt = Math.round(DateTime.fromISO(da).diff($now, 'hours').hours * 10) / 10; } catch (e) { hoursToAppt = null; }
  }
  const dueSoon = (hoursToAppt !== null && hoursToAppt <= apptWindowHours);
  if (silent || dueSoon) {
    const apptLine = (hoursToAppt === null)
      ? 'no delivery appointment on file'
      : (hoursToAppt < 0 ? (Math.abs(hoursToAppt) + ' hours past the appointment') : (hoursToAppt + ' hours to the appointment'));
    lines.push(r.load_id + ' | ' + (r.customer || 'unknown customer') + ' | status ' + (r.status || 'unknown') + ' | last check in ' + (lc || 'never') + ' | ' + apptLine);
  }
}
return [{ json: {
  today: $now.toFormat('yyyy-LL-dd'),
  active_loads: rows.length,
  stale_count: lines.length,
  stale_lines: lines.length ? lines.join(String.fromCharCode(10)) : 'Every load has a fresh check in and none are due inside 12 hours.'
} }];

const raw = String($json.output || '');
const a = raw.indexOf('{');
const b = raw.lastIndexOf('}');
let p = {};
try { p = JSON.parse(raw.slice(a, b + 1)); } catch (e) { p = {}; }
const src = $('Find Stale Loads').first().json;
const NL = String.fromCharCode(10);
const headline = String(p.headline || ('Morning load brief for ' + src.today));
const digest = String(p.digest || src.stale_lines);
const topAction = String(p.top_action || 'Call the load with the oldest check in first.');
return [{ json: {
  mail_to: 'user@example.com',
  mail_subject: headline + ': ' + src.stale_count + ' load(s) need a call',
  mail_body: 'Loads on the board: ' + src.active_loads + NL
    + 'Loads needing a call: ' + src.stale_count + NL + NL
    + digest + NL + NL
    + 'Top action: ' + topAction + NL + NL
    + 'Lines reviewed:' + NL + src.stale_lines,
  discord_text: ':clipboard: *' + headline + '*' + NL + NL + digest + NL + NL + 'Top action: ' + topAction
} }];
